<?php $editing=$target!==null; $formAction=$editing?'users/'.$target['id']:'profile'; $mapping=['firstname'=>'first_name','middlename'=>'middle_name','lastname'=>'last_name','birthdate'=>'birthdate','gender'=>'gender','email'=>'email','contact'=>'contact_number','address'=>'address','username'=>'username']; ?>
<section class="panel narrow"><h2><?= $editing?'Account information':'Your information' ?></h2><form action="<?= site_url($formAction) ?>" method="post"><?= csrf_field() ?><div class="form-grid">
<?php foreach($mapping as $field=>$column): ?><label for="<?= esc($field,'attr') ?>"><?= esc(ucwords(str_replace('_',' ',$column))) ?><?= $field==='middlename'?' (optional)':'' ?>
<?php if($field==='gender'): ?><select name="gender" id="gender" required><?php foreach(['Male','Female','Prefer not to say'] as $g): ?><option <?= $profile['gender']===$g?'selected':'' ?>><?= esc($g) ?></option><?php endforeach ?></select>
<?php else: $type=['birthdate'=>'date','email'=>'email','contact'=>'tel'][$field]??'text'; ?><input id="<?= esc($field,'attr') ?>" name="<?= esc($field,'attr') ?>" type="<?= $type ?>" value="<?= esc($profile[$column]??'','attr') ?>" <?= $field==='middlename'?'':'required' ?> maxlength="<?= in_array($field,['email','address'],true)?($field==='email'?100:255):50 ?>"><?php endif ?></label><?php endforeach ?></div>
<?php if($editing&&$target['account_type']==='employee'): ?><label>Department<select name="department" required><?php foreach(\App\Libraries\Accounts::DEPARTMENTS as $d): ?><option <?= $target['department']===$d?'selected':'' ?>><?= esc($d) ?></option><?php endforeach ?></select></label><?php if($role==='admin'): ?><label>Authorized role<select name="role" required><?php foreach(['employee','hr','dispatcher','technician'] as $r): ?><option value="<?= $r ?>" <?= $target['role']===$r?'selected':'' ?>><?= esc(ucfirst($r)) ?></option><?php endforeach ?></select></label><?php endif ?><?php endif ?>
<?php if($editing&&$role==='admin'): ?><label>Account access<select name="active"><option value="1" <?= $target['active']?'selected':'' ?>>Active</option><option value="0" <?= !$target['active']?'selected':'' ?>>Deactivated</option></select></label><?php endif ?><button type="submit">Save information</button></form></section>
<?php if(!$editing): ?><section class="panel narrow"><h2>Change password</h2><p>You will be signed out after changing your password.</p><form action="<?= site_url('profile/password') ?>" method="post"><?= csrf_field() ?><label>Current password<input name="current_password" type="password" autocomplete="current-password" required></label><label>New password<input name="new_password" type="password" minlength="8" autocomplete="new-password" required></label><label>Confirm new password<input name="confirm_password" type="password" minlength="8" autocomplete="new-password" required></label><button type="submit">Change password & sign out</button></form></section><?php endif ?>
